import React from "react";
import { IoLocationSharp } from "react-icons/io5";
import { FaEnvelope } from "react-icons/fa6";
import { FACEBOOK_BLUE } from "../../../assets/colors/Colors";
import X from "../../../locust/composables/X";
import "./FooterBasic.css";
import { Center } from "../../../locust/composables/Center";

const VERSION : number = 5

const Footer = ( props : {
    items : { title : any, links : { value : any, href : any }[] }[]
    color ?: string, 
    address ?: any, 
    contact?: any, 
    logo ?: any, 
    sx ?: { logo ?: any }
}) => {

  

  return (
    <div className="Footer">
      
      { props.items.length > 1 &&
        <div className="Foot1">
          { props.items.map(( item : any, index : number )=>{
              return <div key={index}>
                  <ul>
                      <h1>{item.title}</h1>
                      { item.links.map(( link : any, index2 : number )=>{ 
                          
                          return <li key={`${index}-${index2}`}>
                            <a {...{ 
                              ...( link.href ? { href : link.href } : {}),
                              ...( link.onClick ? { onClick : link.onClick } : {}) 
                            }}>{link.value}</a>
                          </li>
                      })}
                  </ul>
              </div>
          })}
          

          <div className="foot-icons">
              { props.logo && <img style={{ marginLeft : 0, marginRight : 20, marginBottom : 20, marginTop : -10, ...props?.sx?.logo   }} src={props.logo} width={200} alt="" /> }
            <div>
            { props.address && 
                <div style={{ padding : 5 }}>
                  <X align="left">
                    <IoLocationSharp />
                    <div style={{ color : props.color ? props.color : FACEBOOK_BLUE, fontSize : 14, marginLeft : 10, marginTop : -2  }}>{ props.address }</div>
                  </X>
                </div>
              }
              { props.contact && 
                <div style={{ padding : 5 }}>
                  <X align="left">
                    <FaEnvelope/>
                    <a style={{ color : props.color ? props.color : FACEBOOK_BLUE, fontSize : 14, marginLeft : 10, marginTop : -2  }} href="">{ props.contact }</a>
                  </X>
                </div>
              }
            </div>
          </div>
        </div>
      }
      { props.items.length <= 1 &&

      
        
          <div className="Foot1" style={{ width : '100%' }}>
            <Center>

            <Center>
              <img src={props.logo} width={200} style={{ ...props?.sx?.logo  }} alt="" />
            </Center>

            { props.items.map(( item : any, index : number )=>{
                return <div key={index}>
                    <ul>
                        <Center>
                          <h1>{item.title}</h1>
                        </Center>
                        { item.links.map(( link : any, index2 : number )=>{ 
                            
                            return <Center><li key={`${index}-${index2}`}>
                                <a {...{ 
                                  ...( link.href ? { href : link.href } : {}),
                                  ...( link.onClick ? { onClick : link.onClick } : {}) 
                                }}>{link.value}</a>
                              </li>
                            </Center>
                        })}
                    </ul>
                </div>
            })}
            

            <div className="foot-icons">
              <div>
                { props.address && 
                    <div style={{ padding : 5 }}>
                      <X align="left">
                        <IoLocationSharp />
                        <div style={{ color : props.color ? props.color : FACEBOOK_BLUE, fontSize : 14, marginLeft : 10, marginTop : -2  }}>{ props.address }</div>
                      </X>
                    </div>
                  }
                  { props.contact && 
                    <div style={{ padding : 5 }}>
                      <X align="left">
                        <FaEnvelope/>
                        <a style={{ color : props.color ? props.color : FACEBOOK_BLUE, fontSize : 14, marginLeft : 10, marginTop : -2  }} href="">{ props.contact }</a>
                      </X>
                    </div>
                  }
              </div>
            </div>
            </Center>
          </div>
        
      }
    </div>
  );
};

export default Footer;
